import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        print("RLM_SESSION_DIR not set")
        return {}

    session_jsonl = os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl')
    print(f"Looking for: {session_jsonl}")

    try:
        with open(session_jsonl, 'r') as f:
            content = f.read()
    except Exception as e:
        print(f"Error reading session file: {e}")
        return {}

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]

    print(f"Loaded grids: {list(G.keys())}")
    for k, g in G.items():
        print(f"\n{g}-way grid:")
        for row in g:
            print(row)

    return G

G = load_grids()

